}

/* Info */
[data-testid="stAlert"]:has([data-testid="stAlertContentInfo"]) {
  background: rgba(0, 210, 255, 0.06) !important;
  border-color: rgba(0, 210, 255, 0.35) !important;
  color: #b8eeff !important;
}
[data-testid="stAlertContainer"]:has([data-testid="stAlertContentInfo"]) {
  background: rgba(0, 210, 255, 0.06) !important;
  border-radius: inherit !important;
}

/* Warning */
[data-testid="stAlert"]:has([data-testid="stAlertContentWarning"]) {
  background: rgba(255, 214, 0, 0.06) !important;
  border-color: rgba(255, 214, 0, 0.35) !important;
  color: #fff3b0 !important;
}
[data-testid="stAlertContainer"]:has([data-testid="stAlertContentWarning"]) {
  background: rgba(255, 214, 0, 0.06) !important;
  border-radius: inherit !important;
}

/* Success */
[data-testid="stAlert"]:has([data-testid="stAlertContentSuccess"]) {
  background: rgba(0, 255, 135, 0.06) !important;
  border-color: rgba(0, 255, 135, 0.35) !important;
  color: #b0ffe0 !important;
}
[data-testid="stAlertContainer"]:has([data-testid="stAlertContentSuccess"]) {
  background: rgba(0, 255, 135, 0.06) !important;
  border-radius: inherit !important;
}

/* Error */
[data-testid="stAlert"]:has([data-testid="stAlertContentError"]) {
  background: rgba(255, 61, 90, 0.06) !important;
  border-color: rgba(255, 61, 90, 0.35) !important;
  color: #ffc0c8 !important;
}
[data-testid="stAlertContainer"]:has([data-testid="stAlertContentError"]) {
  background: rgba(255, 61, 90, 0.06) !important;
  border-radius: inherit !important;
}

/* ─── Radio Buttons ───────────────────────────────────────────────────────────*/
[data-testid="stRadio"] > label {
  color: var(--text-muted) !important;
  font-family: var(--font-display) !important;
  font-size: 0.85rem !important;
  font-weight: 500 !important;
  letter-spacing: 0.04em !important;
  text-transform: uppercase !important;
  margin-bottom: 0.5rem !important;
}

[data-testid="stRadio"] [data-baseweb="radio"] {
  padding: 0.5rem 0.75rem !important;
  border-radius: var(--border-radius-sm) !important;
  transition: background 0.2s ease !important;
  margin-bottom: 2px !important;
}

[data-testid="stRadio"] [data-baseweb="radio"]:hover {
  background: rgba(0, 255, 135, 0.05) !important;
}

[data-testid="stRadio"] [data-baseweb="radio"] [data-checked="true"] ~ span,
[data-testid="stRadio"] [aria-checked="true"] ~ div {
  color: var(--primary-color) !important;
}

/* ─── Tabs ────────────────────────────────────────────────────────────────────*/
[data-testid="stTabs"] [data-baseweb="tab-list"] {
  background: transparent !important;
  border-bottom: 1px solid var(--border-color) !important;
  gap: 0.5rem !important;
  overflow-x: auto !important;
  flex-wrap: nowrap !important;
  -webkit-overflow-scrolling: touch !important;
  scrollbar-width: none !important;
}
[data-testid="stTabs"] [data-baseweb="tab-list"]::-webkit-scrollbar {
  display: none !important;
}

[data-testid="stTabs"] [data-baseweb="tab"] {
  background: transparent !important;
  border-radius: var(--border-radius-sm) var(--border-radius-sm) 0 0 !important;
  color: var(--text-muted) !important;
  font-family: var(--font-display) !important;
  font-weight: 600 !important;
  font-size: 0.85rem !important;
  letter-spacing: 0.03em !important;
  padding: 0.6rem 1.2rem !important;
  transition: background-color 0.2s ease, border-color 0.2s ease, color 0.2s ease !important;
  border-bottom: 2px solid transparent !important;
}

[data-testid="stTabs"] [aria-selected="true"] {
  color: var(--primary-color) !important;
  border-bottom-color: var(--primary-color) !important;
  background: rgba(0, 255, 135, 0.05) !important;
}

/* ─── Code / Monospace Blocks ────────────────────────────────────────────────*/
code, pre {
  font-family: var(--font-mono) !important;
  background: rgba(14, 21, 36, 0.9) !important;
  border: 1px solid var(--border-color) !important;
  border-radius: var(--border-radius-sm) !important;
  color: var(--primary-color) !important;
  font-size: 0.82rem !important;
}

/* ─── Selectbox / Multiselect tags ───────────────────────────────────────────*/
[data-baseweb="tag"] {
  background: rgba(0, 255, 135, 0.12) !important;
  border: 1px solid rgba(0, 255, 135, 0.3) !important;
  border-radius: 4px !important;
  color: var(--primary-color) !important;
  font-family: var(--font-mono) !important;
  font-size: 0.78rem !important;
}

/* ─── Spinner / Progress ─────────────────────────────────────────────────────*/
/* Native st.spinner is hidden everywhere — the app uses the glassmorphic
   loading_overlay() component for user-facing loading feedback instead. */
[data-testid="stSpinner"] {
  display: none !important;
}

/* Discreet inline status line — for loading feedback lighter than
   loading_overlay(), e.g. background quote fetches triggered by a
   selection change rather than an explicit button click. */
.discreet-status {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.82rem;
  color: var(--text-muted);
  padding: 0.4rem 0;
}
.discreet-status::before {
  content: '';
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--brand-primary);
  animation: discreet-status-pulse 1.1s ease-in-out infinite;
}
@keyframes discreet-status-pulse {
  0%, 100% { opacity: 0.3; }
  50% { opacity: 1; }
}

/* ─── Slider ─────────────────────────────────────────────────────────────────*/
[data-baseweb="slider"] [data-testid="stThumbValue"] {
  background: var(--primary-color) !important;
  color: var(--bg-color) !important;
  font-family: var(--font-mono) !important;
  font-weight: 700 !important;
}

[data-baseweb="slider"] [role="slider"] {
  background: var(--primary-color) !important;
  border-color: var(--primary-color) !important;
}

/* ─── Sidebar — remove green success box, use subtle label ───────────────────*/
[data-testid="stSidebar"] [data-testid="stAlert"] {
  background: rgba(0, 255, 135, 0.04) !important;
  border-color: rgba(0, 255, 135, 0.2) !important;
  font-size: 0.8rem !important;
}

/* ─── Divider ─────────────────────────────────────────────────────────────────*/
hr {
  border: none !important;
  border-top: 1px solid var(--border-color) !important;
  margin: 1.5rem 0 !important;
  opacity: 0.6 !important;
}

/* ─── Section label utility (replaces <br><br> spacers) ─────────────────────*/
.section-spacer { height: 1.5rem; }

/* ─── Primary button variant ─────────────────────────────────────────────────*/
[data-testid="baseButton-primary"] {
  background: linear-gradient(135deg, rgba(0,255,135,0.15) 0%, rgba(0,210,255,0.08) 100%) !important;
  border-color: var(--primary-color) !important;
  color: var(--primary-color) !important;
  box-shadow: 0 0 12px rgba(0,255,135,0.2), var(--shadow-dark) !important;
}

[data-testid="baseButton-primary"]:hover {
  box-shadow: 0 0 20px rgba(0,255,135,0.4), var(--shadow-dark) !important;
  transform: translateY(-2px) !important;
}


/* Styling numbers & tables specifically with Monospace */
td, th, .stMetric, [data-testid="stMetricValue"] {
  font-family: var(--font-mono) !important;
}

/* Card / Container styling */
.element-container iframe {
  border-radius: var(--border-radius-lg);
}

/* Streamlit Native Card & Metric Styling */
[data-testid="stMetric"] {
  background-color: var(--panel-bg) !important;
  border: 1px solid var(--border-color) !important;
  border-radius: var(--border-radius-md) !important;
  padding: 1rem 0.75rem !important;
  box-shadow: var(--shadow-dark) !important;
  transition: border-color 0.3s ease, box-shadow 0.3s ease, transform 0.3s ease !important;
}

[data-testid="stMetric"]:hover {
  border-color: var(--primary-color) !important;
  box-shadow: var(--shadow-glow), var(--shadow-dark) !important;
  transform: translateY(-2px);
}

[data-testid="stMetricValue"],
[data-testid="stMetricValue"] > div {
  color: var(--primary-color) !important;
  font-size: 1.65rem !important;
  font-weight: 700 !important;
  white-space: nowrap !important;
}

[data-testid="stMetricLabel"],
[data-testid="stMetricLabel"] > div {
  color: var(--text-muted) !important;
  font-weight: 500 !important;
  text-transform: uppercase;
  font-size: 0.7rem !important;
  letter-spacing: 0.05em;
  white-space: normal !important;
}

/* Form containers */
[data-testid="stForm"] {
  background-color: var(--panel-bg) !important;
  border: 1px solid var(--border-color) !important;
  border-radius: var(--border-radius-lg) !important;
  padding: 2rem !important;
  box-shadow: var(--shadow-dark) !important;
}

/* Sleek Inputs styling */
.stTextInput input, .stNumberInput input, .stDateInput input {
  background-color: rgba(8, 12, 20, 0.8) !important;
  border: 1px solid var(--border-color) !important;
  color: var(--text-main) !important;
  border-radius: var(--border-radius-md) !important;
  padding: 0.6rem 1rem !important;
  transition: border-color 0.2s ease, box-shadow 0.2s ease !important;
  font-family: var(--font-mono) !important;
}

.stSelectbox div[data-baseweb="select"] > div, .stMultiSelect div[data-baseweb="select"] > div {
  background-color: rgba(8, 12, 20, 0.8) !important;
  border: 1px solid var(--border-color) !important;
  color: var(--text-main) !important;
  border-radius: var(--border-radius-md) !important;
  transition: border-color 0.2s ease, box-shadow 0.2s ease !important;
  font-family: var(--font-mono) !important;
}

.stTextInput input:focus, .stNumberInput input:focus, .stDateInput input:focus,
.stSelectbox div[data-baseweb="select"]:focus-within > div,
.stMultiSelect div[data-baseweb="select"]:focus-within > div {
  border-color: var(--secondary-color) !important;
  box-shadow: 0 0 0 2px rgba(0, 210, 255, 0.2) !important;
  outline: none !important;
}

/* Custom styled card classes for raw HTML output */
.financial-panel {
  background-color: var(--panel-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--border-radius-lg);
  padding: 1.5rem;
  margin-bottom: 1.5rem;
  box-shadow: var(--shadow-dark);
}

.glow-panel {
  border-color: var(--primary-color);
  box-shadow: var(--shadow-glow), var(--shadow-dark);
}

/* High-craft Buttons */
.stButton>button, .stDownloadButton>button, .stFormSubmitButton>button {
  background: linear-gradient(135deg, #0e1b2f 0%, #080c14 100%) !important;
  color: var(--text-main) !important;
  border: 1px solid var(--border-color) !important;
  border-radius: var(--border-radius-md) !important;
  padding: 0.6rem 1.8rem !important;
  font-family: var(--font-display) !important;
  font-weight: 600 !important;
  letter-spacing: 0.02em !important;
  cursor: pointer !important;
  transition: background-color 0.3s ease, border-color 0.3s ease, color 0.3s ease, box-shadow 0.3s ease, transform 0.3s ease !important;
  box-shadow: var(--shadow-dark) !important;
  width: 100%;
}

.stButton>button:hover, .stDownloadButton>button:hover, .stFormSubmitButton>button:hover {
  border-color: var(--primary-color) !important;
  color: var(--primary-color) !important;
  box-shadow: var(--shadow-glow), var(--shadow-dark) !important;
  transform: translateY(-1px);
}

.stButton>button:active, .stDownloadButton>button:active, .stFormSubmitButton>button:active {
  transform: translateY(1px);
}

/* Table styling override */
.dataframe {
  border-collapse: collapse !important;
  border: 1px solid var(--border-color) !important;
  border-radius: var(--border-radius-md) !important;
  overflow: hidden !important;
}

.dataframe th {
  background-color: #0f172a !important;
  color: var(--text-main) !important;
  font-weight: 600 !important;
  border-bottom: 2px solid var(--border-color) !important;
  padding: 10px 15px !important;
  text-align: left !important;
}

.dataframe td {
  background-color: var(--panel-bg) !important;
  color: var(--text-muted) !important;
  border-bottom: 1px solid var(--border-color) !important;
  padding: 10px 15px !important;
}

.dataframe tr:hover td {
  background-color: #161f38 !important;
  color: var(--text-main) !important;
}

/* Badge style */
.badge {
  display: inline-block;
  padding: 0.25em 0.6em;
  font-size: 75%;
  font-weight: 700;
  line-height: 1;
  text-align: center;
  white-space: nowrap;
  vertical-align: baseline;
  border-radius: 10rem;
  background-color: rgba(0, 255, 135, 0.1);
  color: var(--primary-color);
  border: 1px solid rgba(0, 255, 135, 0.3);
  font-family: var(--font-mono);
}

/* Custom CSS to inject space/styling adjustments */
.spacer-sm { margin-bottom: 0.5rem; }
.spacer-md { margin-bottom: 1.5rem; }
.spacer-lg { margin-bottom: 3rem; }

/* Premium Glassmorphic Loading Spinner */
.loading-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 3rem;
  background: rgba(14, 21, 36, 0.6);
  backdrop-filter: blur(10px);
  border: 1px solid var(--border-color);
  border-radius: var(--border-radius-lg);
  box-shadow: var(--shadow-dark);
  margin: 2rem 0;
  text-align: center;
}

.loading-spinner {
  width: 60px;
  height: 60px;
  border: 4px solid rgba(0, 255, 135, 0.1);
  border-left-color: var(--primary-color);
  border-right-color: var(--secondary-color);
  border-radius: 50%;
  animation: spin-glow 1.2s cubic-bezier(0.5, 0, 0.5, 1) infinite;
  box-shadow: 0 0 15px rgba(0, 255, 135, 0.2);
}

.loading-text {
  margin-top: 1.5rem;
  color: var(--text-main);
  font-family: var(--font-display);
  font-weight: 600;
  letter-spacing: 0.05em;
  animation: pulse-glow 2s ease-in-out infinite;
}

@keyframes spin-glow {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

@keyframes pulse-glow {
  0%, 100% { opacity: 0.6; text-shadow: 0 0 5px rgba(0, 210, 255, 0); }
  50% { opacity: 1; text-shadow: 0 0 10px rgba(0, 210, 255, 0.4); }
}

.loading-tickers {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  justify-content: center;
  margin-top: 1.1rem;
  max-width: 420px;
}

.loading-ticker-chip {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--text-muted);
  background: rgba(0, 255, 135, 0.06);
  border: 1px solid rgba(0, 255, 135, 0.18);
  border-radius: 999px;
  padding: 0.25rem 0.7rem;
  animation: chip-glow 1.6s ease-in-out infinite;
}
.loading-ticker-chip:nth-child(2n) { animation-delay: 0.2s; }
.loading-ticker-chip:nth-child(3n) { animation-delay: 0.4s; }
.loading-ticker-chip:nth-child(4n) { animation-delay: 0.6s; }
.loading-ticker-chip:nth-child(5n) { animation-delay: 0.8s; }

@keyframes chip-glow {
  0%, 100% { opacity: 0.55; border-color: rgba(0, 255, 135, 0.18); color: var(--text-muted); }
  50% { opacity: 1; border-color: rgba(0, 255, 135, 0.5); color: var(--primary-color); }
}

.loading-bar-track {
  position: relative;
  width: 220px;
  height: 4px;
  margin-top: 1.4rem;
  border-radius: 999px;
  background: rgba(148, 163, 184, 0.15);
  overflow: hidden;
}

.loading-bar-fill {
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  width: 35%;
  border-radius: 999px;
  background: var(--brand-gradient);
  box-shadow: 0 0 8px rgba(0, 255, 135, 0.4);
  animation: bar-sweep 1.3s ease-in-out infinite;
}

@keyframes bar-sweep {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(385%); }
}

/* ─── Responsive Card Grid (CSS flex — replaces st.columns for cards) ───────*/
.mcard-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 0.65rem;
  margin-bottom: 0.75rem;
}
.mcard {
  flex: 1 1 130px;
  background: linear-gradient(135deg, #0e1726, #070c14);
  border: 1px solid #1e293b;
  border-radius: 10px;
  padding: 0.85rem 0.7rem;
  text-align: center;
  box-shadow: 0 4px 6px -1px rgba(0,0,0,0.15);
  min-height: 78px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.mcard:hover {
  border-color: rgba(0, 255, 135, 0.3);
  box-shadow: 0 0 10px rgba(0,255,135,0.07), 0 4px 6px -1px rgba(0,0,0,0.15);
}
.mcard-label {
  font-size: 0.7rem;
  color: #94a3b8;
  font-weight: 600;
  text-transform: uppercase;
  margin-bottom: 0.3rem;
  letter-spacing: 0.05em;
  word-break: break-word;
  line-height: 1.3;
}
.mcard-value {
  font-size: 1rem;
  font-weight: 800;
  font-family: 'JetBrains Mono', monospace;
  word-break: break-word;
  overflow-wrap: anywhere;
  line-height: 1.3;
}

/* ─── Page Hero Header ──────────────────────────────────────────────────────*/
.page-hero {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  background: linear-gradient(135deg, #0e1b2f 0%, #080c14 100%);
  border: 1px solid var(--border-color);
  border-left: 4px solid var(--primary-color);
  border-radius: var(--border-radius-lg);
  padding: 1.5rem 2rem;
  margin-bottom: 2rem;
  box-shadow: var(--shadow-dark), inset 0 0 60px rgba(0, 255, 135, 0.03);
  position: relative;
  overflow: hidden;
}

.page-hero::after {
  content: '';
  position: absolute;
  top: -50%;
  right: -10%;
  width: 300px;
  height: 300px;
  background: radial-gradient(circle, rgba(0, 210, 255, 0.06) 0%, transparent 70%);
  pointer-events: none;
}

.page-hero-icon {
  width: 72px;
  height: 72px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  filter: drop-shadow(0 0 16px rgba(0, 255, 135, 0.35));
  transition: filter 0.3s ease, transform 0.3s ease;
}

.page-hero:hover .page-hero-icon {
  filter: drop-shadow(0 0 24px rgba(0, 255, 135, 0.6));
  transform: scale(1.05);
}

.main-hero .page-hero-icon {
  filter: drop-shadow(0 0 16px rgba(0, 210, 255, 0.35));
}

.main-hero:hover .page-hero-icon {
  filter: drop-shadow(0 0 24px rgba(0, 210, 255, 0.6));
}

.page-hero-content { flex: 1; }

.page-hero-title {
  font-family: var(--font-display) !important;
  font-size: 1.7rem !important;
  font-weight: 700 !important;
  margin: 0 0 0.35rem !important;
  padding: 0 !important;
  background: linear-gradient(135deg, var(--text-main) 40%, var(--secondary-color) 100%);
  -webkit-background-clip: text !important;
  -webkit-text-fill-color: transparent !important;
  letter-spacing: -0.03em !important;
}

.page-hero-subtitle {
  font-family: var(--font-display);
  font-size: 0.9rem;
  color: var(--text-muted);
  margin: 0;
  line-height: 1.5;
}

.main-hero { border-left-color: var(--secondary-color); }
.main-hero .page-hero-icon { filter: drop-shadow(0 0 12px rgba(0, 210, 255, 0.4)); }
.main-hero::after { background: radial-gradient(circle, rgba(0, 255, 135, 0.06) 0%, transparent 70%); }

/* ─── Mobile Responsiveness ─────────────────────────────────────────────────*/
@media (max-width: 768px) {

  /* Hero compacto */
  .page-hero {
    flex-direction: row !important;
    align-items: flex-start;
    gap: 0.65rem;
    padding: 1.1rem 1rem;
    margin-bottom: 1.25rem;
  }
  .page-hero-icon { width: 52px; height: 52px; }
  .page-hero-title { font-size: 1.25rem !important; }
  .page-hero-subtitle { font-size: 0.8rem; }

  /* Reduz padding geral do app */
  .main .block-container {
    padding: 0.75rem 0.75rem 2rem !important;
    max-width: 100% !important;
  }

  /* Métricas compactas */
  [data-testid="stMetric"] { padding: 0.75rem !important; }
  [data-testid="stMetricValue"],
  [data-testid="stMetricValue"] > div { font-size: 1.35rem !important; }

  /* Tabelas com scroll horizontal */
  [data-testid="stDataFrame"], .stDataFrame {
    overflow-x: auto !important;
    -webkit-overflow-scrolling: touch !important;
  }

  /* Forms sem padding excessivo */
  [data-testid="stForm"] { padding: 1rem !important; }

  /* Sidebar overlay no mobile */
  [data-testid="stSidebar"] {
    width: 85vw !important;
    max-width: 320px !important;
  }

  /* Botões touch-friendly (44px mínimo per HIG) */
  .stButton > button,
  .stDownloadButton > button,
  .stFormSubmitButton > button {

    padding: 0.75rem 1rem !important;
    font-size: 0.9rem !important;
    min-height: 44px !important;
  }

  /* Scrollbar discreta no mobile */
  ::-webkit-scrollbar { width: 3px; height: 3px; }

  /* Gráficos sem overflow horizontal */
  .js-plotly-plot, .plot-container {
    max-width: 100% !important;
    overflow: hidden !important;
  }
  .modebar { display: none !important; }

  /* Colunas Streamlit: wrap mas sem forçar 100% ainda */
  [data-testid="stHorizontalBlock"] {
    flex-wrap: wrap !important;
    gap: 0.5rem !important;
  }

  /* Tabs: fonte menor para caber mais tickers */
  [data-testid="stTabs"] [data-baseweb="tab"] {
    padding: 0.5rem 0.8rem !important;
    font-size: 0.78rem !important;
    white-space: nowrap !important;
  }

  /* Inputs: altura mínima para toque confortável */
  .stNumberInput input { min-height: 44px !important; font-size: 1rem !important; }
  .stSelectbox div[data-baseweb="select"] > div,
  .stMultiSelect div[data-baseweb="select"] > div { min-height: 44px !important; }

  /* Sliders: área de toque maior */
  [data-baseweb="slider"] { padding: 0.5rem 0 !important; }
}

@media (max-width: 480px) {
  /* Colunas Streamlit: largura total em telas muito pequenas */
  [data-testid="stHorizontalBlock"] > div {
    min-width: min(100%, 260px) !important;
  }

  /* Métricas ainda menores */
  [data-testid="stMetricValue"],
  [data-testid="stMetricValue"] > div {
    font-size: 1.1rem !important;
    white-space: normal !important;
  }
  [data-testid="stMetricLabel"],
  [data-testid="stMetricLabel"] > div { font-size: 0.6rem !important; }

  /* Cards de texto compactos */
  .mcard { min-height: 68px; padding: 0.65rem 0.5rem; }
  .mcard-value { font-size: 0.88rem !important; }

  /* Hero mínimo */
  .page-hero { padding: 0.85rem !important; }
  .page-hero-title { font-size: 1.05rem !important; }
  .page-hero-icon { width: 40px; height: 40px; }
}

/* News card styles */
.news-card {
  background-color: var(--panel-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--border-radius-md);
  padding: 1.2rem;
  margin-bottom: 1rem;
  box-shadow: var(--shadow-dark);
  transition: border-color 0.3s ease, box-shadow 0.3s ease, transform 0.3s ease;
}

.news-card:hover {
  border-color: var(--secondary-color);
  box-shadow: 0 0 15px rgba(0, 210, 255, 0.15), var(--shadow-dark);
  transform: translateY(-2px);
}

.news-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 0.6rem;
}

.news-provider {
  color: var(--secondary-color);
  font-size: 0.75rem;
  font-weight: 700;
  font-family: var(--font-mono);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.news-date {
  color: var(--text-muted);
  font-size: 0.72rem;
  font-family: var(--font-mono);
}

.news-title-link {
  color: var(--text-main) !important;
  text-decoration: none !important;
  transition: color 0.2s ease;
}

.news-title-link:hover {
  color: var(--primary-color) !important;
}

.news-title-link:focus-visible {
  outline: 2px solid var(--primary-color);
  outline-offset: 2px;
  border-radius: 2px;
}

.news-title {
  margin: 0 0 0.6rem 0 !important;
  font-size: 1.05rem !important;
  line-height: 1.4 !important;
  font-weight: 600 !important;
}

.news-summary {
  color: var(--text-muted);
  font-size: 0.85rem;
  margin: 0;
  line-height: 1.5;
}

/* ─── Metric Delta Color Override ────────────────────────────────────────────*/
[data-testid="stMetricDelta"] svg { display: none !important; }
[data-testid="stMetricDelta"] > div {
  font-family: var(--font-mono) !important;
  font-size: 0.72rem !important;
  font-weight: 700 !important;
  letter-spacing: 0.04em !important;
  padding: 2px 8px !important;
  border-radius: 4px !important;
  display: inline-block !important;
}
/* Positive delta */
[data-testid="stMetricDelta"][data-testid-delta-direction="up"] > div,
[data-testid="stMetricDelta"].stMetricDeltaPositive > div {
  color: #00ff87 !important;
  background: rgba(0, 255, 135, 0.08) !important;
  border: 1px solid rgba(0, 255, 135, 0.2) !important;
}
/* Negative delta */
[data-testid="stMetricDelta"][data-testid-delta-direction="down"] > div,
[data-testid="stMetricDelta"].stMetricDeltaNegative > div {
  color: #ff3d5a !important;
  background: rgba(255, 61, 90, 0.08) !important;
  border: 1px solid rgba(255, 61, 90, 0.2) !important;
}

/* ─── Download Button Distinct Style ─────────────────────────────────────────*/
[data-testid="stDownloadButton"] > button {
  background: linear-gradient(135deg, rgba(0,210,255,0.1) 0%, rgba(0,210,255,0.04) 100%) !important;
  border-color: rgba(0, 210, 255, 0.4) !important;
  color: #00d2ff !important;
  font-size: 0.82rem !important;
  padding: 0.45rem 1rem !important;
}

[data-testid="stDownloadButton"] > button:hover {
  border-color: #00d2ff !important;
  box-shadow: 0 0 16px rgba(0, 210, 255, 0.3), var(--shadow-dark) !important;
  transform: translateY(-1px) !important;
  color: #00d2ff !important;
}

/* ─── Expander Improvements ───────────────────────────────────────────────────*/
[data-testid="stExpander"] {
  border: 1px solid var(--border-color) !important;
  border-radius: var(--border-radius-md) !important;
  background: rgba(14, 21, 36, 0.5) !important;
  margin-bottom: 0.5rem !important;
  overflow: hidden !important;
}

[data-testid="stExpander"] summary {
  padding: 0.75rem 1rem !important;
  cursor: pointer !important;
  font-family: var(--font-display) !important;
  font-size: 0.83rem !important;
  font-weight: 600 !important;
  color: var(--text-muted) !important;
  transition: color 0.2s ease, background 0.2s ease !important;
  border-radius: var(--border-radius-md) !important;
}

[data-testid="stExpander"] summary:hover {
  color: var(--text-main) !important;
  background: rgba(0, 255, 135, 0.03) !important;
}

[data-testid="stExpander"][open] summary {
  color: var(--text-main) !important;
  border-bottom: 1px solid var(--border-color) !important;
  border-radius: var(--border-radius-md) var(--border-radius-md) 0 0 !important;
}

[data-testid="stExpander"] > div:last-child {
  padding: 1rem !important;
}

/* ─── Caption / Small Text Improvements ──────────────────────────────────────*/
[data-testid="stCaptionContainer"], .stCaption {
  color: #64748b !important;
  font-size: 0.75rem !important;
  font-family: var(--font-display) !important;
  line-height: 1.5 !important;
}

/* ─── Number Input Hide Arrows (cleaner look) ────────────────────────────────*/
.stNumberInput input[type="number"]::-webkit-outer-spin-button,
.stNumberInput input[type="number"]::-webkit-inner-spin-button {
  -webkit-appearance: none !important;
  margin: 0 !important;
}
.stNumberInput input[type="number"] { -moz-appearance: textfield !important; }

/* ─── Animated Gradient Border for Scorecards ────────────────────────────────*/
@keyframes gradient-border {
  0% { border-color: rgba(0, 255, 135, 0.5); box-shadow: 0 0 12px rgba(0, 255, 135, 0.2); }
  50% { border-color: rgba(0, 210, 255, 0.5); box-shadow: 0 0 20px rgba(0, 210, 255, 0.25); }
  100% { border-color: rgba(0, 255, 135, 0.5); box-shadow: 0 0 12px rgba(0, 255, 135, 0.2); }
}
.scorecard-animated {
  animation: gradient-border 3s ease-in-out infinite;
}

/* ─── Utility Card Classes ────────────────────────────────────────────────────*/
.card-positive {
  border-color: rgba(0, 255, 135, 0.35) !important;
  box-shadow: 0 0 12px rgba(0, 255, 135, 0.08), var(--shadow-dark) !important;
}
.card-negative {
  border-color: rgba(255, 61, 90, 0.35) !important;
  box-shadow: 0 0 12px rgba(255, 61, 90, 0.08), var(--shadow-dark) !important;
}
.card-neutral {
  border-color: rgba(255, 214, 0, 0.3) !important;
  box-shadow: 0 0 12px rgba(255, 214, 0, 0.06), var(--shadow-dark) !important;
}

/* ─── Sidebar Footer / Branding ──────────────────────────────────────────────*/
.sidebar-footer {
  position: fixed;
  bottom: 0;
  left: 0;
  width: inherit;
  padding: 0.75rem 1rem;
  background: var(--panel-bg);
  border-top: 1px solid var(--border-color);
  font-size: 0.7rem;
  color: #475569;
  font-family: var(--font-mono);
  letter-spacing: 0.04em;
  z-index: 1000;
}

/* ─── Selectbox Open Dropdown Styling ────────────────────────────────────────*/
[data-baseweb="popover"] [data-baseweb="menu"] {
  background: #0e1524 !important;
  border: 1px solid var(--border-color) !important;
  border-radius: var(--border-radius-md) !important;
  box-shadow: 0 20px 40px rgba(0,0,0,0.6) !important;
}
[data-baseweb="popover"] [role="option"] {
  color: var(--text-muted) !important;
  font-family: var(--font-mono) !important;
  font-size: 0.82rem !important;
  padding: 0.5rem 1rem !important;
  transition: background 0.15s ease !important;
}
[data-baseweb="popover"] [role="option"]:hover,
[data-baseweb="popover"] [role="option"][aria-selected="true"] {
  background: rgba(0, 255, 135, 0.07) !important;
  color: var(--primary-color) !important;
}

/* ─── Form Submit Button (primary) ───────────────────────────────────────────*/
[data-testid="stFormSubmitButton"] > button {
  background: linear-gradient(135deg, rgba(0,255,135,0.15) 0%, rgba(0,210,255,0.08) 100%) !important;
  border-color: var(--primary-color) !important;
  color: var(--primary-color) !important;
  font-size: 0.95rem !important;
  font-weight: 700 !important;
  letter-spacing: 0.04em !important;
  padding: 0.75rem 2rem !important;
  box-shadow: 0 0 16px rgba(0,255,135,0.2) !important;
}
[data-testid="stFormSubmitButton"] > button:hover {
  box-shadow: 0 0 28px rgba(0,255,135,0.4) !important;
  transform: translateY(-2px) !important;
}


/* ─── Progress Bar ────────────────────────────────────────────────────────────*/
[data-testid="stProgress"] > div > div {
  background: linear-gradient(90deg, var(--primary-color), var(--secondary-color)) !important;
  border-radius: 4px !important;
}
[data-testid="stProgress"] > div {
  background: rgba(30, 41, 59, 0.5) !important;
  border-radius: 4px !important;
}

/* ─── UI refinement pass ────────────────────────────────────────────────────
   Keep the B3Lab dark identity while improving hierarchy, rhythm and focus. */
:root {
  --content-max-width: 1440px;
  --surface-glass: rgba(14, 21, 36, 0.72);
  --surface-hover: rgba(19, 29, 46, 0.94);
  --focus-ring: 0 0 0 3px rgba(0, 210, 255, 0.22);
}

/* Give the content a calmer reading width and a more deliberate top rhythm. */
.main .block-container {
  max-width: var(--content-max-width) !important;
  padding-top: 3rem !important;
  padding-bottom: 4rem !important;
}

/* Reduce the visual noise of Streamlit's default vertical gaps. */
[data-testid="stVerticalBlock"] > [data-testid="stVerticalBlock"] {
  gap: 0.85rem;
}

/* Consistent interactive affordances. */
button,
[data-baseweb="select"],
[data-testid="stExpander"] summary,
[data-testid="stTabs"] [data-baseweb="tab"] {
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible,
input:focus-visible,
textarea:focus-visible,
[data-baseweb="select"]:focus-within,
[data-testid="stExpander"] summary:focus-visible {
  outline: none !important;
  box-shadow: var(--focus-ring) !important;
}

/* Buttons: less glow, stronger contrast, clearer hierarchy. */
[data-testid="stButton"] > button {
  min-height: 2.5rem;
  border-radius: 9px !important;
  border-color: #2a3a50 !important;
  background: rgba(19, 29, 46, 0.82) !important;
  color: var(--text-main) !important;
  font-family: var(--font-display) !important;
  font-weight: 600 !important;
  transition: transform 160ms ease, border-color 160ms ease, background 160ms ease, box-shadow 160ms ease !important;
}
[data-testid="stButton"] > button:hover {
  transform: translateY(-1px) !important;
  border-color: rgba(0, 210, 255, 0.65) !important;
  background: var(--surface-hover) !important;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.22) !important;
}
[data-testid="baseButton-primary"] {
  background: linear-gradient(110deg, rgba(0, 255, 135, 0.2), rgba(0, 210, 255, 0.14)) !important;
}

/* Make the hero feel like a product header instead of a large empty banner. */
.page-hero {
  min-height: 122px;
  background:
    radial-gradient(circle at 90% 15%, rgba(0, 210, 255, 0.12), transparent 34%),
    linear-gradient(135deg, rgba(14, 27, 47, 0.98), rgba(8, 12, 20, 0.96)) !important;
  border-color: rgba(71, 91, 118, 0.7) !important;
  box-shadow: 0 18px 42px rgba(0, 0, 0, 0.22), inset 0 1px 0 rgba(255, 255, 255, 0.035) !important;
}
.page-hero-title { font-size: clamp(1.5rem, 2.3vw, 2rem) !important; }
.page-hero-subtitle { max-width: 760px; font-size: 0.95rem; }

/* Tables read as data products, not raw Streamlit output. */
[data-testid="stDataFrame"] {
  border: 1px solid var(--panel-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.18);
}

/* Keep content comfortable on narrow screens. */
@media (max-width: 768px) {
  .main .block-container {
    padding-top: 4rem !important;
    padding-bottom: 2.5rem !important;
  }
  .page-hero { min-height: 0; }
  [data-testid="stButton"] > button { min-height: 2.75rem; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
}

/* ─── Selector polish ────────────────────────────────────────────────────────*/
.stMultiSelect [data-baseweb="select"] input::placeholder,
.stSelectbox [data-baseweb="select"] input::placeholder {
  color: #94a3b8 !important;
  opacity: 1 !important;
}
.stMultiSelect [data-baseweb="select"] input,
.stSelectbox [data-baseweb="select"] input {
  caret-color: var(--brand-secondary) !important;
}
[data-testid="stTooltipHoverTarget"] {
  color: var(--brand-secondary) !important;
}

[data-testid="stTooltipHoverTarget"] > div {
  color: #475569 !important;
  transition: color 0.2s ease !important;
}
[data-testid="stTooltipHoverTarget"] > div:hover { color: var(--secondary-color) !important; }
[data-testid="stTooltipContent"] {
  background: #0f1a2e !important;
  border: 1px solid rgba(0, 210, 255, 0.25) !important;
  border-radius: var(--border-radius-md) !important;
  color: var(--text-main) !important;
  font-family: var(--font-display) !important;
  font-size: 0.78rem !important;
  box-shadow: 0 8px 24px rgba(0,0,0,0.5) !important;
  max-width: 280px !important;
  padding: 0.6rem 0.9rem !important;
  line-height: 1.5 !important;
}

/* ─── Plotly Chart Border Radius ─────────────────────────────────────────────*/
.js-plotly-plot .plotly {
  border-radius: var(--border-radius-md) !important;
  overflow: hidden !important;
}

/* ─── Checkbox Styling ───────────────────────────────────────────────────────*/
[data-testid="stCheckbox"] label {
  font-family: var(--font-display) !important;
  font-size: 0.85rem !important;
  color: var(--text-muted) !important;
  transition: color 0.2s ease !important;
}
[data-testid="stCheckbox"] label:hover { color: var(--text-main) !important; }
[data-testid="stCheckbox"] [data-baseweb="checkbox"] [data-checked="true"] div {
  background: var(--primary-color) !important;
  border-color: var(--primary-color) !important;
}

/* ─── Multiselect Dropdown Improvements ──────────────────────────────────────*/
[data-baseweb="tag"] span { font-size: 0.75rem !important; }
[data-baseweb="tag"] [role="button"] { opacity: 0.7 !important; }
[data-baseweb="tag"] [role="button"]:hover { opacity: 1 !important; }

/* ─── Hero hover animation ───────────────────────────────────────────────────*/
.page-hero {
  transition: box-shadow 0.3s ease, border-color 0.3s ease !important;
}
.page-hero:hover {
  border-left-color: var(--secondary-color) !important;
  box-shadow: var(--shadow-dark), 0 0 30px rgba(0, 210, 255, 0.08) !important;
}
.main-hero:hover { border-left-color: var(--primary-color) !important; }

/* ─── Hide Streamlit Native Loading Indicators ───────────────────────────────*/
/* Top progress decoration bar */
[data-testid="stDecoration"] { display: none !important; }
/* Top-right running/status widget */
[data-testid="stStatusWidget"] { display: none !important; }
/* Native spinner text (we use glassmorphic spinners instead) */
[data-testid="stSpinner"] > div > p { display: none !important; }
/* Hide Streamlit top toolbar when in embedded/app mode */
[data-testid="stToolbar"] { display: none !important; }
/* Hide "Made with Streamlit" footer */
footer { display: none !important; }
footer::after { display: none !important; }
#MainMenu { display: none !important; }

/* ─── UI polish pass — clearer hierarchy for the analysis workspace ───────── */
.ui-section-heading {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  margin: 1.65rem 0 0.75rem !important;
  padding: 0 0 0.65rem !important;
  border-bottom: 1px solid rgba(71, 91, 118, 0.5);
  font-size: clamp(1rem, 1.45vw, 1.2rem) !important;
  letter-spacing: -0.015em !important;
}

.analyst-synthesis-heading {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 0 0.5rem !important;
}

.analyst-synthesis-heading svg {
  flex-shrink: 0;
}

.analyst-synthesis-title {
  color: var(--text-main) !important;
}

.analyst-synthesis-guide {
  margin: -0.15rem 0 0.8rem !important;
  padding-left: 0.6rem;
  border-left: 2px solid var(--brand-primary);
  color: var(--text-muted);
  font-size: 0.76rem;
}

.analyst-synthesis-card {
  margin: 0 0 0.8rem;
  padding: 1rem 1.1rem;
  border: 1px solid color-mix(in srgb, var(--panel-border) 78%, var(--brand-primary));
  border-radius: var(--radius-lg);
  background:
    radial-gradient(circle at 100% 0, rgba(97, 212, 198, 0.08), transparent 36%),
    linear-gradient(145deg, var(--panel-bg), #101722);
  box-shadow: 0 10px 24px rgba(0, 0, 0, 0.16);
}

.analyst-synthesis-card-header,
.analyst-synthesis-identity {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.6rem;
}

.analyst-synthesis-identity {
  justify-content: flex-start;
  flex-wrap: wrap;
}

.analyst-synthesis-identity strong {
  color: var(--brand-secondary);
  font-family: var(--font-mono);
  font-size: 0.95rem;
}

.analyst-synthesis-identity span {
  color: var(--text-main);
  font-size: 0.86rem;
  font-weight: 600;
}

.analyst-synthesis-sector {
  margin-top: 0.15rem;
  color: var(--text-faint);
  font-size: 0.7rem;
}

.analyst-category.is-positive { --analyst-signal: var(--brand-primary); }
.analyst-category.is-neutral { --analyst-signal: var(--brand-accent); }
.analyst-category.is-negative { --analyst-signal: var(--brand-danger); }

.analyst-synthesis-summary {
  display: flex;
  align-items: baseline;
  gap: 0.55rem;
  margin: 0.75rem 0 0.35rem !important;
  color: var(--text-muted);
  font-size: 0.8rem;
}

.analyst-synthesis-summary strong {
  color: var(--text-main);
  font-family: var(--font-mono);
  font-size: 1.05rem;
}

.analyst-synthesis-insufficient {
  color: var(--text-muted);
}

.analyst-category-grid {
  margin: 0 !important;
}

.analyst-category {
  min-height: 105px;
  justify-content: flex-start;
  gap: 0.35rem;
  padding: 0.75rem 0.65rem;
}

.analyst-category-status {
  color: var(--analyst-signal) !important;
  font-family: var(--font-display) !important;
  font-size: 0.85rem !important;
}

.analyst-synthesis-meter {
  width: min(100%, 120px);
  height: 4px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(174, 186, 202, 0.14);
}

.analyst-synthesis-meter span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--analyst-signal);
}

.analyst-synthesis-percentile {
  color: var(--text-faint);
  font-size: 0.66rem;
}

.analyst-synthesis-empty {
  margin: 0.4rem 0 !important;
  color: var(--text-muted);
  font-size: 0.78rem;
}

.analyst-synthesis-details {
  margin-top: 0.65rem;
  padding-top: 0.55rem;
  border-top: 1px solid rgba(71, 91, 118, 0.5);
}

.analyst-synthesis-details summary {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  color: var(--brand-secondary);
  font-size: 0.74rem;
  font-weight: 600;
  cursor: pointer;
  list-style: none;
}

.analyst-synthesis-details summary::-webkit-details-marker { display: none; }
.analyst-synthesis-details summary::after {
  margin-left: auto;
  content: "+";
  color: var(--text-faint);
  font-size: 1rem;
}
.analyst-synthesis-details[open] summary::after { content: "−"; }
.analyst-synthesis-details summary span {
  color: var(--text-faint);
  font-size: 0.66rem;
}

.analyst-synthesis-detail-body > p {
  margin: 0.55rem 0 0.35rem !important;
  color: var(--text-faint);
  font-size: 0.66rem;
}

.analyst-synthesis-detail-group {
  margin-top: 0.45rem;
}

.analyst-synthesis-detail-group strong {
  color: var(--text-muted);
  font-size: 0.7rem;
}

.analyst-synthesis-detail-group ul {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 0.25rem 1rem;
  margin: 0.25rem 0 0 !important;
  padding-left: 1rem;
  color: var(--text-muted);
  font-size: 0.7rem;
}

@media (max-width: 520px) {
  .analyst-synthesis-card { padding: 0.85rem; }
  .analyst-synthesis-card-header { align-items: flex-start; }
  .analyst-category { flex-basis: 115px; }
}


.ui-section-heading::after {
  content: '';
  align-self: flex-end;
  width: 2.25rem;
  height: 2px;
  margin-left: auto;

