/* Flat empty state and loading state shared by secondary pages. */
.empty-state-card,
.loading-container {
  background: #11181d !important;
  border: 1px solid #293840 !important;
  border-radius: 8px !important;
  box-shadow: none !important;
}

.loading-container {
  padding: 1.6rem !important;
}

.loading-spinner {
  border-color: #2d3d44 !important;
  border-top-color: #9ad7b1 !important;
  box-shadow: none !important;
}

.loading-bar-track {
  background: #243138 !important;
}

.loading-bar-fill {
  background: #9ad7b1 !important;
  box-shadow: none !important;
}

[data-testid="stForm"] {
  background: #11181d !important;
  border-color: #293840 !important;
  border-radius: 8px !important;
  box-shadow: none !important;
}

[data-testid="stExpander"] {
  background: #11181d !important;
  border-color: #293840 !important;
  box-shadow: none !important;
}

[data-testid="stExpander"] summary:hover {
  background: #172126 !important;
}

[data-testid="stTabs"] [aria-selected="true"] {
  background: #18251f !important;
  color: var(--brand-primary) !important;
  border-bottom-color: var(--brand-primary) !important;
}

[data-testid="stAlert"],
[data-testid="stAlertContainer"] {
  box-shadow: none !important;
}


@media (max-width: 768px) {
  .page-hero {
    padding: 0.95rem !important;
  }

  .page-hero-icon {
    width: 34px !important;
    height: 34px !important;
  }

  .page-hero-title {
    font-size: 1.35rem !important;
  }

  .page-hero-subtitle {
    font-size: 0.82rem !important;
  }

  .onboarding-card {
    padding: 0.95rem !important;
  }
}
.selection-summary-source {
  text-transform: none !important;
}

.empty-state-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  margin-top: 1.4rem;
  padding: 2rem 1.4rem;
  text-align: center;
}

.empty-state-card svg {
  width: 42px;
  height: 42px;
  margin-bottom: 0.8rem;
  opacity: 0.65;
}

.empty-state-title {
  margin-bottom: 0.35rem;
  color: var(--text-main);
  font-size: 1.05rem;
  font-weight: 650;
}

.empty-state-message {
  max-width: 420px;
  margin-bottom: 0.25rem;
  color: var(--text-muted);
  font-size: 0.86rem;
  line-height: 1.55;
}

.empty-state-message strong {
  color: var(--brand-primary) !important;
}
.metric-section-heading {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  margin: 1.25rem 0 0.55rem;
  color: #b8c9bd;
  font-size: 0.82rem;
  font-weight: 650;
  letter-spacing: 0.02em;
}

.metric-section-heading svg {
  width: 15px;
  height: 15px;
  opacity: 0.68;
}

.selection-active-note {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.8rem;
  margin-bottom: 0.55rem;
  padding: 0.62rem 0.8rem;
  border: 1px solid #30453a;
  border-left: 2px solid #8fbfa0;
  border-radius: 6px;
  background: #111b16;
  color: #aab9ae;
  font-size: 0.82rem;
  line-height: 1.4;
}

.selection-active-note strong {
  color: #c7e3cf;
}

.selection-active-note-hint {
  flex-shrink: 0;
  color: #86a390;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

@media (max-width: 640px) {
  .selection-active-note {
    align-items: flex-start;
    flex-direction: column;
    gap: 0.25rem;
  }
}
/* Normalize legacy HTML fragments still emitted by data panels. */
[style*="linear-gradient"],
[style*="radial-gradient"] {
  background-image: none !important;
  background: #11181d !important;
}

[style*="box-shadow"] {
  box-shadow: none !important;
}

[style*="-webkit-text-fill-color"] {
  background: none !important;
  -webkit-background-clip: initial !important;
  background-clip: initial !important;
  -webkit-text-fill-color: var(--text-main) !important;
  color: var(--text-main) !important;
}
@media (max-width: 480px) {
  .page-hero {
    display: block !important;
    overflow: visible !important;
  }

  .page-hero-icon {
    display: none !important;
  }

  .page-hero-content {
    max-width: 100%;
  }
}
/* ─── Research pass: accessibility, touch and numeric readability ─────────── */
html {
  color-scheme: dark;
}

body {
  overflow-x: clip;
}

button,
a,
input,
select,
textarea,
[role="button"] {
  touch-action: manipulation;
}

.page-hero-title,
.page-hero-subtitle,
.ui-section-heading,
.onboarding-title,
.onboarding-description {
  text-wrap: balance;
}

[data-testid="stMetricValue"],
[data-testid="stMetricValue"] > div,
.mcard-value,
td,
th {
  font-variant-numeric: tabular-nums;
}

[data-testid="stSidebar"] {
  overscroll-behavior: contain;
}
/* ─── Colorful sober palette ──────────────────────────────────────────────── */
:root {
  color-scheme: dark;
  --brand-primary: #61d4c6;
  --brand-secondary: #8cb4f2;
  --brand-accent: #e7b96b;
  --brand-danger: #e58a93;
  --brand-info: #b7a2e6;
  --brand-gradient: var(--brand-primary);
  --bg-color: #0b111a;
  --panel-bg: #151d2a;
  --panel-raised: #1d2938;
  --panel-border: #34465b;
  --primary-color: #61d4c6;
  --secondary-color: #8cb4f2;
  --accent-color: #e7b96b;
  --border-color: #34465b;
  --text-main: #f0f4f8;
  --text-muted: #aebaca;
  --text-faint: #748297;
  --surface-glass: #151d2a;
  --surface-hover: #202d3c;
  --sidebar-bg: #101824;
  --border-subtle: #28384b;
  --border-strong: #405873;
  --control-bg: #182433;
  --content-max-width: 1360px;
  --focus-ring: 0 0 0 3px rgba(97, 212, 198, 0.3);
}

html,
body,
.stApp,
[data-testid="stAppViewContainer"] {
  background: var(--bg-color) !important;
  color: var(--text-main) !important;
}

[data-testid="stSidebar"] {
  background: var(--sidebar-bg) !important;
  border-right-color: var(--border-subtle) !important;
}

[data-testid="stSidebarNavLink"] span {
  color: var(--text-muted) !important;
}

[data-testid="stSidebarNavLink"]:hover {
  background: var(--surface-hover) !important;
}

[data-testid="stSidebarNavLink"][aria-current="page"] {
  background: rgba(97, 212, 198, 0.12) !important;
  border-left-color: var(--brand-primary) !important;
}

[data-testid="stSidebarNavLink"][aria-current="page"] span {
  color: var(--brand-primary) !important;
}

.sidebar-section-label {
  border-bottom-color: var(--border-subtle) !important;
  color: var(--text-muted) !important;
  font-size: 0.72rem !important;
  letter-spacing: 0 !important;
  text-transform: none !important;
}
.page-hero[data-page="home"] { --page-accent: var(--brand-primary); }
.page-hero[data-page="portfolio"] { --page-accent: var(--brand-secondary); }
.page-hero[data-page="simulation"] { --page-accent: var(--brand-info); }
.page-hero[data-page="news"] { --page-accent: var(--brand-accent); }
.page-hero[data-page="valuation"] { --page-accent: var(--brand-danger); }
.page-hero[data-page="screener"] {
  --page-accent: color-mix(in srgb, var(--brand-secondary) 70%, var(--brand-info));
}


.page-hero,
.main-hero {
  display: flex !important;
  align-items: center !important;
  gap: 1rem !important;
  min-height: 0 !important;
  margin: 0 0 1.25rem !important;
  padding: 0 0 1.1rem !important;
  border: 0 !important;
  border-bottom: 1px solid color-mix(in srgb, var(--page-accent, var(--brand-primary)) 42%, var(--border-subtle)) !important;
  border-radius: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
}

.page-hero:hover,
.main-hero:hover {
  box-shadow: none !important;
}

.page-hero-icon,
.main-hero .page-hero-icon {
  display: flex !important;
  flex: 0 0 42px !important;
  align-items: center !important;
  justify-content: center !important;
  width: 42px !important;
  height: 42px !important;
  padding: 0 !important;
  border-color: color-mix(in srgb, var(--page-accent, var(--brand-primary)) 48%, var(--border-subtle)) !important;
  border-radius: 8px !important;
  background: color-mix(in srgb, var(--page-accent, var(--brand-primary)) 14%, var(--panel-bg)) !important;
  color: var(--page-accent, var(--brand-primary)) !important;
  filter: none !important;
  opacity: 1 !important;
  box-shadow: none !important;
}

.page-hero-icon svg {
  width: 25px !important;
  height: 25px !important;
  max-width: none !important;
  max-height: none !important;
  filter: none !important;
}

.page-hero-content {
  min-width: 0;
}
.page-hero-title {
  -webkit-text-fill-color: var(--page-accent, var(--text-main)) !important;
  color: var(--page-accent, var(--text-main)) !important;
}


.page-hero-subtitle {
  color: var(--text-muted) !important;
}

.stButton > button,
.stDownloadButton > button,
.stFormSubmitButton > button,
[data-testid="stFormSubmitButton"] > button {
  background: var(--control-bg) !important;
  border-color: var(--border-strong) !important;
  color: var(--text-main) !important;
}

.stButton > button:hover,
.stDownloadButton > button:hover,
.stFormSubmitButton > button:hover,
[data-testid="stFormSubmitButton"] > button:hover {
  background: var(--surface-hover) !important;
  border-color: var(--brand-secondary) !important;
  color: var(--text-main) !important;
}

[data-testid="baseButton-primary"],
[data-testid="stFormSubmitButton"] > button {
  background: var(--brand-primary) !important;
  border-color: var(--brand-primary) !important;
  color: #0b111a !important;
}

[data-testid="baseButton-primary"]:hover,
[data-testid="stFormSubmitButton"] > button:hover {
